<script lang="ts">
export interface MarqueeRectType {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Collection of rectangles defining user generated regions
 */
const rectangles: MarqueeRectType[] = [];
// Temp variables
let startX = 0;
let startY = 0;

const marqueeRect: MarqueeRectType = {
  x: 0,
  y: 0,
  width: 0,
  height: 0,
};

const $ = document.querySelector.bind(document);
let screenshot: Element;
let marquee: Element;
let boxes: Element;


import helperMixin from '../mixins/helperMixin.js';
import { defineComponent } from 'vue';

export default defineComponent({
  el: '#app',
  
  mixins: [helperMixin],
  data() {
    return {
      imageHeight: 0,
      imageWidth: 0,
      viewBox: '0 0 0 0',
      // Form field values for inputs
      receiptNo: '',
      receiptDate: '',
      receiptTime: '',
      tableNo: '',
      currency: '',
      total: '',
      netto: '',
      taxAmount: '',
      tip: '',
      taxRate: '',
      taxTotal: '',
      taxAmountField: '',
      withholding: '',
      vendorName: '',
      vendorTaxId: '',
      vendorAddress: '',
      vendorPhone: '',
      lineItemsQ: '',
    };
  },
  mounted: function () {
    // this.$nextTick(function () {
    marquee = $('#marquee') as HTMLElement;
    screenshot = $('.screenshot') as HTMLElement;
    boxes = $('#boxes') as HTMLElement;

    marquee.classList.add('hide');

    // set the width of image
    let imageElm = $('#image_container') as HTMLElement;
    this.imageWidth = imageElm.offsetWidth;
    this.imageHeight = imageElm.offsetHeight;

    this.viewBox =
      '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);

    // screenshot.addEventListener('pointerdown', this.startDrag);
    // })
  },
  methods: {
    goToLineItems() {
      this.$router.push('/tbl_ext_v3');
    },
    startDrag(ev: any) {
      let height = 0;
      let width = 0;

      if (ev.button === 1) {
        const rect = this.hitTest(ev.layerX, ev.layerY);
        if (rect) {
          rectangles.splice(rectangles.indexOf(rect), 1);
          this.redraw();
        }
        return;
      }

      // window.addEventListener('pointerup', this.stopDrag);
      // screenshot.addEventListener('pointermove', this.moveDrag.bind(this));
      marquee.classList.remove('hide');
      startX = ev.layerX;
      startY = ev.layerY;

      Object.assign(marqueeRect, { startX, startY, width, height });
      this.drawRect(marquee, marqueeRect);
    },

    stopDrag(ev: any) {
      marquee.classList.add('hide');
      screenshot.removeEventListener('pointerup', this.stopDrag.bind(this));
      screenshot.removeEventListener('pointermove', this.moveDrag.bind(this)); //.bind(this)
      if (ev.target === screenshot && marqueeRect.width && marqueeRect.height) {
        logInfo(marqueeRect);
        rectangles.push(Object.assign({}, marqueeRect));
        this.redraw();
      }
    },

    moveDrag(ev: any) {
      let x = ev.layerX;
      let y = ev.layerY;
      let width = startX - x;
      let height = startY - y;
      if (width < 0) {
        width *= -1;
        x -= width;
      }
      if (height < 0) {
        height *= -1;
        y -= height;
      }
      Object.assign(marqueeRect, { x, y, width, height });
      this.drawRect(marquee, marqueeRect);
    },

    hitTest(x: number, y: number) {
      return rectangles.find(
        (rect) =>
          x >= rect.x &&
          y >= rect.y &&
          x <= rect.x + rect.width &&
          y <= rect.y + rect.height,
      );
    },

    redraw() {
      boxes.innerHTML = '';
      rectangles.forEach((data: any) => {
        boxes.appendChild(
          this.drawRect(
            document.createElementNS('http://www.w3.org/2000/svg', 'rect'),
            data,
          ),
        );
      });
    },

    drawRect(rect: any, data: any): any {
      if (typeof data == 'object') {
        const { x, y, width, height } = data;
        rect.setAttributeNS(null, 'width', width);
        rect.setAttributeNS(null, 'height', height);
        rect.setAttributeNS(null, 'x', x);
        rect.setAttributeNS(null, 'y', y);
      }
      return rect;
    },
  },
});
</script>

